const journalArticles = require('./journal-articles.json');
function journalEscape(value){return String(value).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function journalReadingTime(article){
 if(article.wordCount)return Math.max(1,Math.ceil(article.wordCount/200))+' min read';
 const text=[article.title,article.description,...article.paragraphs,'A conversation worth having. Every property has its own context. A clear brief helps the people involved discuss the decisions ahead with a shared understanding of the intended hospitality experience.'].join(' ');
 return Math.max(1,Math.ceil(text.trim().split(/\s+/).length/200))+' min read';
}
function journalDate(article){return '<time datetime="'+article.publishedAt+'">'+new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(article.publishedAt+'T00:00:00Z'))+'</time>';}
function journalCard(article){return `<article class="insight-card" data-journal-card data-category="${article.category}" data-search="${journalEscape((article.title+' '+article.topic+' '+article.description).toLowerCase())}"><a class="insight-card-link" href="article-${article.slug}.html"><div class="insight-card-image">${image(article.image,article.imageAlt||article.topic+' hospitality imagery')}</div><div class="insight-card-meta"><span>${article.category}</span><span>${article.topic}</span></div><h2>${article.title}</h2><p class="insight-card-description">${article.description}</p><div class="insight-card-foot"><span class="journal-card-dateline">${journalDate(article)}<span aria-hidden="true">·</span><span>${journalReadingTime(article)}</span><span aria-hidden="true">·</span><span>by Zenith Hospitality</span></span><span aria-hidden="true">↗</span></div></a></article>`;}
