pages['404']=['Page not found','Find your way back to Zenith Hospitality Global.',`<section class="wrap not-found" aria-labelledby="not-found-title"><div class="not-found-copy"><p class="eyebrow">404 / Page not found</p><h1 id="not-found-title">A little off<br>the beaten path.</h1><p>The page you’re looking for may have moved, or the address may be incorrect. Let’s get you back to familiar ground.</p><div class="not-found-actions">${link('index.html','Back to home','button gold')}${link('contact.html','Contact us','button outline')}</div><a class="not-found-services" href="index.html#services">Explore our expertise &amp; services <span aria-hidden="true">↗</span></a></div><figure class="not-found-image">${image('wellness.jpg','A quiet courtyard and reflecting pool at a tropical hospitality retreat').replace('loading="lazy"','loading="eager"')}</figure></section>`];

for(const [slug,[rawTitle,rawDescription,content]] of Object.entries(pages)){
 const title=journalEscape(rawTitle),description=journalEscape(rawDescription);
 const html=`<!doctype html>\n<!-- Assumptions: isolated Nivara-inspired dark direction; generated concept imagery, no unapproved assignments. See brand-spec.md and direction-approved.md. -->\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} | Zenith Hospitality Global</title><meta name="description" content="${description}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f8f9fb"><meta property="og:title" content="${title} | Zenith Hospitality Global"><meta property="og:description" content="${description}"><meta property="og:type" content="website"><meta property="og:image" content="assets/resort.jpg"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;1,400&family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><script defer src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script><link rel="stylesheet" href="styles.css"><script defer src="assets/lenis.min.js"></script><script defer src="smooth-scroll.js"></script><script defer src="assets/gsap.min.js"></script><script defer src="back-navigation.js"></script><script defer src="app.js"></script><script defer src="hero-slideshow.js"></script>${slug==='insights'?'<script defer src="journal.js"></script>':''}${slug==='expertise'?'<script defer src="expertise-tabs.js"></script>':''}${slug==='index'?'<script defer src="service-pathways.js"></script>':''}${slug==='index'?'<script defer src="assets/lottie-light.min.js"></script><script defer src="lottie-init.js"></script><link rel="preload" as="image" href="assets/zenith-original-hero-1.jpg">':''}</head><body class="${slug==='index'?'home':'inner-page'}">${slug==='index'?'<script src="intro.js"></script>':''}${header(slug)}${slug!=='index'?'<a class="expertise-back" href="index.html" data-back-link aria-label="Go back"><img class="circle-arrow" src="assets/icons/arrow-left.svg" alt="" aria-hidden="true" width="22" height="22"></a>':''}<main id="main">${content}</main>${footer()}<a class="floating-whatsapp" href="https://wa.me/6282144807110" target="_blank" rel="noopener noreferrer" aria-label="Chat with Zenith on WhatsApp (opens in a new tab)"><span class="whatsapp-tooltip" aria-hidden="true">Chat with us</span><img src="assets/whatsapp.svg" alt="" width="28" height="28"></a></body></html>`;
 // Preserve the page content for later reactivation while redirecting its public route.
 const output = slug==='404'
  ? html.replace('<head>','<head><base href="/">')
  : slug==='expertise'
  ? html.replace('<head>', '<head><meta http-equiv="refresh" content="0;url=index.html#services"><script>location.replace("index.html#services");</script>')
  : html;
 fs.writeFileSync(path.join(root,slug+'.html'),output);
}
